// Regenerates ProbeGuardVectors.sol: probe contents and what the off-chain twin (`isSafeProbe` in
// packages/node/src/payments/evm/tokenizer-probe-guard.ts) says about them, so the Solidity test checks the
// on-chain guard gives the same answer. Every range edge, both sides of it, plus the classes honest engines
// count differently. Run from the repo root after `pnpm run build`:
//   node packages/contracts/test/fixtures/tokenizer-probe-guard/generate.mjs
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { PROBE_GUARD_RANGES, isSafeProbe } from '../../../../node/dist/payments/evm/tokenizer-probe-guard.js'

const here = dirname(fileURLToPath(import.meta.url))
const encoder = new TextEncoder()
const vectors = []
const add = (bytes) => vectors.push({ bytes, safe: isSafeProbe(bytes) })
const text = (value) => add(encoder.encode(value))

// Each range's edges and their neighbours, between ASCII letters.
for (const [start, end] of PROBE_GUARD_RANGES) {
  for (const codePoint of new Set([start - 1, start, end, end + 1])) {
    if (codePoint >= 0xd800 && codePoint <= 0xdfff) continue
    text(` a${String.fromCodePoint(codePoint)}b`)
  }
}
// Every printable ASCII byte before and after each sequence opener.
for (let c = 0x20; c < 0x7f; c++) {
  for (const opener of ['<', '[', "'"]) text(` x${opener}${String.fromCharCode(c)}y`)
}
for (const value of [
  ' a </s>', ' a <|im_end|>', ' a [INST]', " it's", ' a <', ' ESPAÑA', ' é', ' 가', ' 👍\u{1f3fb}',
  ' ❤️', ' 👨‍👩', ' \u{1f914}', ' 龦', 'no space', '  two', ' ',
  ' My budget is 450 € and my friend said “obrigado” 😅 — here is my plan: `trip.days = 9`',
  ' 내일 회의는 3시에 시작해요. 東京の天気はどうですか、明日は雨かな。', ' שלום מה שלומך, привет как дела, españa, γεια σου',
]) text(value)
for (const bytes of [[0x20, 0x41, 0x09], [0x20, 0x41, 0x7f], [0x20, 0x41, 0xc0, 0xaf], [0x20, 0x41, 0xe0, 0x82, 0xa3], [0x20, 0x41, 0xed, 0xa0, 0x80], [0x20, 0x41, 0xe4, 0xb8], [0x20, 0x41, 0x80], [0x20, 0x41, 0xf4, 0x90, 0x80, 0x80], [0x20, 0x41, 0xf8, 0x88, 0x80, 0x80, 0x80], [0x20, 0x41, 0xc2, 0xa3]]) {
  add(Uint8Array.from(bytes))
}

const hex = (bytes) => Buffer.from(bytes).toString('hex')
const lines = vectors.map((v, i) => `        (b[${i}], safe[${i}]) = (hex"${hex(v.bytes)}", ${v.safe});`)
writeFileSync(join(here, 'ProbeGuardVectors.sol'), `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @dev Generated by generate.mjs; do not edit. Probe contents and the off-chain guard's answer for each
///      (${vectors.filter((v) => v.safe).length} safe, ${vectors.filter((v) => !v.safe).length} refused).
library ProbeGuardVectors {
    function all() internal pure returns (bytes[] memory b, bool[] memory safe) {
        b = new bytes[](${vectors.length});
        safe = new bool[](${vectors.length});
${lines.join('\n')}
    }
}
`)
console.log(`wrote ProbeGuardVectors.sol (${vectors.length} vectors)`)
